import sqlite3
import sys
import json
import hmac
import hashlib
import requests
import os
from urllib.parse import urlparse

def compute_signature(body, secret):
    body_str = json.dumps(body, sort_keys=True).encode('utf-8')
    return hmac.new(secret.encode('utf-8'), body_str, hashlib.sha256).hexdigest()

def process_input():
    db_path, table_name, column_name, webhook_url = sys.argv[1:]
    secret = os.getenv('WEBHOOK_SECRET')
    if not secret:
        print("Error: WEBHOOK_SECRET environment variable not set", file=sys.stderr)
        sys.exit(1)

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    for line in sys.stdin:
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        try:
            id_value = line
            query = f"SELECT * FROM {table_name} WHERE {column_name} = ?"
            cursor.execute(query, (id_value,))
            row = cursor.fetchone()

            if row:
                columns = [desc[0] for desc in cursor.description]
                body = {col: row[i] for i, col in enumerate(columns) if col != column_name}
                body[id_value] = row[0] if columns else None  # Ensure id is included

                # Sort columns alphabetically
                sorted_body = {k: body[k] for k in sorted(body.keys())}
                signature = compute_signature(sorted_body, secret)

                headers = {'X-Signature': signature}
                try:
                    response = requests.post(webhook_url, json=sorted_body, headers=headers)
                    print(f"{id_value}: {response.status_code}")
                except requests.RequestException:
                    print(f"{id_value}: error")
            else:
                print(f"{id_value}: not found")
        except Exception as e:
            print(f"{id_value}: error", file=sys.stderr)

    conn.close()

if __name__ == "__main__":
    if len(sys.argv) != 5:
        print("Usage: python notify.py <db_path> <table_name> <column_name> <webhook_url>", file=sys.stderr)
        sys.exit(1)
    process_input()
